mapper.select:
SELECT a.id, t.`name` AS type_name, a.theme, a.`name`, a.content, a.address, a.organizer, a.phone, a.active_date, a.active_picture FROM active a LEFT JOIN active_type t ON t.id = a.type_id
a.del_flag = 'N'
AND NOT EXISTS ( SELECT 1 FROM active_participant ap WHERE ap.active_id = a.id AND NOT EXISTS ( SELECT 1 FROM elder e WHERE e.id = ap.elder_id
) )
AND a.name LIKE concat('%', #{keyQuery.name,jdbcType=VARCHAR}, '%')
AND t.id = #{keyQuery.typeId}
AND a.active_date >= #{startTime}
AND a.active_date <= #{endTime}
ORDER BY a.id DESC
